// ENG-24452: the artifact path-hygiene gate must reject absolute checkout
// paths in demo surface dist trees, tolerate only the documented
// pre-0.1.5 portable-artifact pins, and stay wired into the canonical proof
// AFTER the in-place surface rebuild so it scans regenerated bytes.

import { strict as assert } from 'node:assert';
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import {
  PRE_PORTABLE_ARTIFACT_EXACT_CONTRACT_VERSIONS,
  auditSurfaceDistTrees,
  collectSurfaceDistTrees,
  pinnedExactContractVersion,
  scanArtifactBytes,
} from '../scripts/check-artifact-path-hygiene.mjs';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const scratch = mkdtempSync(join(tmpdir(), 'artifact-path-hygiene-'));

function surface(demoId, surfaceName, { pin, distFiles }) {
  const surfaceDir = join(scratch, 'demos', demoId, 'surfaces', surfaceName);
  mkdirSync(join(surfaceDir, 'dist', 'web', 'assets'), { recursive: true });
  if (pin !== undefined) {
    writeFileSync(join(surfaceDir, 'package.json'), JSON.stringify({
      dependencies: { '@exact/contract': `npm:@ccheever/exact-contract@${pin}` },
    }));
  }
  for (const [name, content] of Object.entries(distFiles)) {
    writeFileSync(join(surfaceDir, 'dist', 'web', 'assets', name), content);
  }
  return surfaceDir;
}

try {
  const demosDir = join(scratch, 'demos');

  // Marker detection over raw bytes.
  assert.deepEqual(scanArtifactBytes('const x = 1;\n'), [], 'clean content has no findings');
  assert.equal(scanArtifactBytes('p="/Users/somebody/projects/app.contract"')[0]?.marker, 'macos-home');
  assert.equal(scanArtifactBytes('p="/home/runner/work/checkout/x.ts"')[0]?.marker, 'linux-home');
  assert.equal(scanArtifactBytes('p="/tmp/exact-worktree/x.ts"')[0]?.marker, 'posix-tmp');
  assert.equal(scanArtifactBytes('p="/private/tmp/exact-worktree/x.ts"')[0]?.marker, 'posix-tmp');
  assert.equal(scanArtifactBytes('p="/var/folders/xy/build/x.ts"')[0]?.marker, 'macos-var');
  assert.equal(scanArtifactBytes('p="/private/var/folders/xy/build/x.ts"')[0]?.marker, 'macos-var');
  assert.equal(scanArtifactBytes('p="C:\\\\Users\\\\dev\\\\x.ts"')[0]?.marker, 'windows-home');
  assert.equal(
    scanArtifactBytes('p="/workspace/exact/src/compiler.ts"')[0]?.marker,
    'posix-ci-root',
  );
  assert.equal(
    scanArtifactBytes('p="/opt/build/exact/src/compiler.ts"')[0]?.marker,
    'posix-ci-root',
  );
  assert.equal(
    scanArtifactBytes('p="D:\\\\a\\\\exact\\\\exact\\\\src\\\\compiler.ts"')[0]?.marker,
    'windows-drive-root',
  );
  assert.deepEqual(
    scanArtifactBytes(
      'import "/__exact_app__/main.ts"; import "/__exact_runtime__/router.ts"; ' +
      'import "/__exact_workspace__/demos/shared/model.mjs";',
    ),
    [],
    'Exact portable app/runtime/workspace tokens are not host paths',
  );
  assert.equal(
    scanArtifactBytes('at /srv/checkouts/snapback/app', {
      extraMarkers: [{ id: 'checkout-root', pattern: /\/srv\/checkouts\/snapback/ }],
    })[0]?.marker,
    'checkout-root',
    'the runner-supplied literal checkout root is a first-class marker',
  );
  const capped = scanArtifactBytes('/Users/a/b '.repeat(50));
  assert.equal(capped.length, 5, 'findings are capped per file');
  const excerpted = scanArtifactBytes(`${'x'.repeat(200)}/Users/somebody/leak.ts${'y'.repeat(200)}`);
  assert.match(excerpted[0].excerpt, /x+\/Users\/somebody\/leak\.tsy+/, 'excerpts carry surrounding context');

  // Pin extraction only trusts the npm-alias registry shape.
  const pinned = surface('pin-demo', 'contract', { pin: '0.1.2', distFiles: { 'index.js': 'clean' } });
  assert.equal(pinnedExactContractVersion(pinned), '0.1.2');
  const unpinned = surface('pin-demo', 'react', { distFiles: { 'index.js': 'clean' } });
  assert.equal(pinnedExactContractVersion(unpinned), null, 'no package.json means no pin');
  writeFileSync(join(unpinned, 'package.json'), JSON.stringify({
    dependencies: { '@exact/contract': '^1.0.0' },
  }));
  assert.equal(pinnedExactContractVersion(unpinned), null, 'non-alias specs are not registry pins');

  // Inventory derivation: only surfaces with a dist tree participate.
  const noDist = join(scratch, 'demos', 'no-dist-demo', 'surfaces', 'contract');
  mkdirSync(noDist, { recursive: true });
  const inventory = collectSurfaceDistTrees({ demosDir })
    .map(({ demoId, surfaceName }) => `${demoId}/${surfaceName}`);
  assert.ok(inventory.includes('pin-demo/contract'));
  assert.ok(!inventory.includes('no-dist-demo/contract'), 'surfaces without dist are not scanned');

  // A pre-portability pin is skipped even when its dist leaks (the documented
  // ENG-24452/ENG-25004 allowlist), and arms automatically at Exact 0.1.5.
  assert.ok(PRE_PORTABLE_ARTIFACT_EXACT_CONTRACT_VERSIONS.has('0.1.2'));
  assert.ok(PRE_PORTABLE_ARTIFACT_EXACT_CONTRACT_VERSIONS.has('0.1.4'));
  assert.ok(!PRE_PORTABLE_ARTIFACT_EXACT_CONTRACT_VERSIONS.has('0.1.5'));
  surface('leaky-demo', 'contract', {
    pin: '0.1.4',
    distFiles: { 'index-HASH.js': 'sourcePath:`/Users/somebody/projects/checkout/app.contract`' },
  });
  surface('armed-demo', 'contract', {
    pin: '0.1.5',
    distFiles: { 'index-HASH.js': 'sourcePath:`/Users/somebody/projects/checkout/app.contract`' },
  });
  surface('clean-demo', 'contract', {
    pin: '0.1.5',
    distFiles: {
      'index-HASH.js':
        'sourcePath:`app.contract`,file:`helpers.contract-meta.ts`,workspace:`/__exact_workspace__/shared.ts`',
    },
  });
  const audited = new Map(
    auditSurfaceDistTrees({ demosDir, checkoutRoot: '/srv/checkouts/snapback' })
      .map((result) => [result.id, result]),
  );
  assert.equal(audited.get('leaky-demo/contract')?.skipped, true, 'pre-fix pins are allowlisted');
  assert.equal(audited.get('leaky-demo/contract')?.findings.length, 0);
  assert.equal(audited.get('armed-demo/contract')?.skipped, false, 'post-fix pins are scanned');
  assert.ok(audited.get('armed-demo/contract')?.findings.length > 0, 'post-fix leaks are findings');
  assert.match(audited.get('armed-demo/contract').findings[0].file, /armed-demo.*index-HASH\.js/);
  assert.equal(audited.get('clean-demo/contract')?.findings.length, 0, 'normalized artifacts pass');
  assert.equal(audited.get('pin-demo/react')?.skipped, false, 'surfaces without a pin are always scanned');

  // The real repository must always be in a passing state: every dist tree
  // is either allowlisted (pre-fix pin) or free of absolute-path markers.
  const repoResults = auditSurfaceDistTrees();
  assert.ok(repoResults.length > 0, 'the tracked cursors-web dist keeps the scan non-vacuous');
  for (const result of repoResults) {
    assert.ok(
      result.skipped || result.findings.length === 0,
      `${result.id} must be allowlisted or clean; findings: ${JSON.stringify(result.findings[0] ?? null)}`,
    );
  }

  // Canonical-proof wiring: the gate runs, and it runs AFTER the in-place
  // required-surface rebuild so it scans freshly regenerated bytes.
  const proof = readFileSync(join(ROOT, 'scripts', 'verify-local-proof'), 'utf8');
  const rebuildIndex = proof.indexOf('check-required-surface-builds.mjs');
  const hygieneIndex = proof.indexOf('check-artifact-path-hygiene.mjs');
  assert.ok(rebuildIndex >= 0, 'verify-local-proof rebuilds required surfaces');
  assert.ok(hygieneIndex >= 0, 'verify-local-proof runs the artifact path-hygiene gate');
  assert.ok(hygieneIndex > rebuildIndex, 'hygiene gate must scan the regenerated artifacts');

  process.stdout.write('artifact_path_hygiene_v0 OK\n');
} finally {
  rmSync(scratch, { recursive: true, force: true });
}
